//! Which application opens a type.
//!
//! Three sources, in the order the association specification gives them: the
//! user's `mimeapps.list`, then the system's, then `mimeinfo.cache` — which is
//! the index of every installed application's `MimeType`, generated by
//! `update-desktop-database`. Scanning every `.desktop` file instead would be a
//! few hundred file reads on the first open.

use std::collections::HashMap;
use std::path::PathBuf;

use crate::entry::DesktopEntry;

/// The association database.
#[derive(Default)]
pub struct Applications {
    /// Type to the ids that claim it, best first.
    handlers: HashMap<String, Vec<String>>,
    /// Type to ids explicitly removed by the user, which override everything.
    removed: HashMap<String, Vec<String>>,
    /// Where `.desktop` files live, most specific first.
    directories: Vec<PathBuf>,
}

impl Applications {
    /// Reads every association database on the machine.
    #[must_use]
    pub fn load() -> Self {
        let directories: Vec<PathBuf> =
            crate::data_dirs().into_iter().map(|dir| dir.join("applications")).collect();
        let mut applications = Self { directories, ..Self::default() };

        // Most specific first, and the first association for a type wins, so a
        // user's choice is never overridden by a package's.
        for dir in crate::config_dirs() {
            applications.absorb_list(&dir.join("mimeapps.list"));
        }
        for dir in applications.directories.clone() {
            applications.absorb_list(&dir.join("mimeapps.list"));
        }
        for dir in applications.directories.clone() {
            applications.absorb_cache(&dir.join("mimeinfo.cache"));
        }
        applications
    }

    fn absorb_list(&mut self, path: &std::path::Path) {
        let Some(text) = crate::read(path) else { return };
        let mut section = String::new();
        for line in text.lines() {
            let line = line.trim();
            if let Some(name) = line.strip_prefix('[').and_then(|rest| rest.strip_suffix(']')) {
                section = name.to_ascii_lowercase();
                continue;
            }
            let Some((mime, ids)) = line.split_once('=') else { continue };
            let ids = ids.split(';').filter(|id| !id.is_empty()).map(str::to_owned);
            match section.as_str() {
                "default applications" | "added associations" => {
                    self.handlers.entry(mime.trim().to_owned()).or_default().extend(ids);
                }
                "removed associations" => {
                    self.removed.entry(mime.trim().to_owned()).or_default().extend(ids);
                }
                _ => {}
            }
        }
    }

    fn absorb_cache(&mut self, path: &std::path::Path) {
        let Some(text) = crate::read(path) else { return };
        for line in text.lines() {
            let line = line.trim();
            if line.starts_with('[') {
                continue;
            }
            let Some((mime, ids)) = line.split_once('=') else { continue };
            let ids = ids.split(';').filter(|id| !id.is_empty()).map(str::to_owned);
            self.handlers.entry(mime.trim().to_owned()).or_default().extend(ids);
        }
    }

    /// The applications that open `mime`, best first.
    ///
    /// Removed associations are dropped, duplicates collapse to their first
    /// appearance, and an entry whose `TryExec` binary is missing is skipped —
    /// packages leave `.desktop` files behind and a menu of things that do
    /// nothing is worse than a shorter menu.
    #[must_use]
    pub fn handlers_for(&self, mime: &str) -> Vec<DesktopEntry> {
        let removed = self.removed.get(mime);
        let mut seen = Vec::new();
        let mut found = Vec::new();
        for id in self.handlers.get(mime).into_iter().flatten() {
            if seen.iter().any(|other| other == id)
                || removed.is_some_and(|list| list.iter().any(|other| other == id))
            {
                continue;
            }
            seen.push(id.clone());
            if let Some(entry) = self.entry(id).filter(DesktopEntry::usable) {
                found.push(entry);
            }
        }
        found
    }

    /// The application that opens `mime`, if any.
    #[must_use]
    pub fn default_for(&self, mime: &str) -> Option<DesktopEntry> {
        self.handlers_for(mime).into_iter().next()
    }

    /// Finds a `.desktop` file by its id.
    ///
    /// An id may contain a dash where the file is in a subdirectory —
    /// `kde-okular.desktop` is `kde/okular.desktop` — which the specification
    /// requires and which is the one piece of this lookup that is not obvious.
    #[must_use]
    pub fn entry(&self, id: &str) -> Option<DesktopEntry> {
        for dir in &self.directories {
            if let Some(entry) = DesktopEntry::open(&dir.join(id)) {
                return Some(entry);
            }
            if let Some(entry) = id
                .split_once('-')
                .and_then(|(prefix, rest)| DesktopEntry::open(&dir.join(prefix).join(rest)))
            {
                return Some(entry);
            }
        }
        None
    }
}

#[cfg(test)]
mod tests {
    #![allow(clippy::expect_used, clippy::unwrap_used)]

    use super::Applications;

    fn database() -> Applications {
        let mut applications = Applications::default();
        applications.absorb_text(
            "[Default Applications]\n\
             text/plain=editor.desktop\n\
             image/png=viewer.desktop;other.desktop\n\
             [Added Associations]\n\
             text/plain=other.desktop\n\
             [Removed Associations]\n\
             image/png=other.desktop\n",
        );
        applications
    }

    impl Applications {
        /// Parsing without a file, for the tests.
        fn absorb_text(&mut self, text: &str) {
            let path = std::env::temp_dir().join(format!(
                "skerry-mimeapps-{}-{:p}.list",
                std::process::id(),
                self
            ));
            std::fs::write(&path, text).unwrap();
            self.absorb_list(&path);
            let _ = std::fs::remove_file(&path);
        }
    }

    #[test]
    fn the_default_comes_before_the_added_associations() {
        let applications = database();
        let ids = applications.handlers.get("text/plain").unwrap();
        assert_eq!(ids, &vec!["editor.desktop".to_owned(), "other.desktop".to_owned()]);
    }

    #[test]
    fn a_removed_association_is_not_offered() {
        let applications = database();
        // `handlers_for` also filters by whether the file exists, so this checks
        // the removal list directly rather than the resolved entries.
        let removed = applications.removed.get("image/png").unwrap();
        assert_eq!(removed, &vec!["other.desktop".to_owned()]);
        assert!(applications.handlers_for("image/png").iter().all(|e| e.id != "other.desktop"));
    }

    #[test]
    fn a_type_nothing_claims_has_no_handler() {
        let applications = database();
        assert!(applications.default_for("application/x-nothing-claims-this").is_none());
    }

    /// The real databases on this machine, if there are any. An assertion about
    /// the machinery, not about what is installed on it.
    #[test]
    fn the_installed_associations_resolve_to_entries_that_exist() {
        let applications = Applications::load();
        for mime in ["text/plain", "text/html", "image/png", "application/pdf"] {
            for entry in applications.handlers_for(mime) {
                assert!(!entry.exec.is_empty(), "`{}` has no Exec", entry.id);
                assert!(entry.path.is_file(), "`{}` came from nowhere", entry.id);
            }
        }
    }
}
